const { execSync } = require('child_process');
const fs = require('fs');

// n8n's webhook node nests the real POST body under `.body` -- fall back
// to the top-level item for non-HTTP (manual) triggers.
const payload = $input.item.json.body || $input.item.json;
const incidentId = payload.incident_id || ('AUDIT-' + Date.now());
const baseUrl = payload.base_url || 'http://host.docker.internal:8099';
const reportPath = '/tmp/newman-' + incidentId.replace(/[^a-zA-Z0-9_-]/g, '') + '-' + Date.now() + '.json';

const collectionUrl = 'https://raw.githubusercontent.com/h-vance/postman-tse-incident-lab/main/postman/tse-api-incident-lab.postman_collection.json';
const environmentUrl = 'https://raw.githubusercontent.com/h-vance/postman-tse-incident-lab/main/postman/tse-local-lab.postman_environment.json';

const cmd = [
  'npx --yes newman run', collectionUrl,
  '-e', environmentUrl,
  '--env-var', 'base_url=' + baseUrl,
  '--reporters json --reporter-json-export', reportPath,
].join(' ');

let execError = null;
try {
  execSync(cmd, { encoding: 'utf-8', maxBuffer: 20 * 1024 * 1024, stdio: ['ignore', 'pipe', 'pipe'] });
} catch (e) {
  // Newman exits non-zero on any failed assertion -- the report file is
  // still written, so this is only fatal if the report never showed up.
  execError = e.message;
}

if (!fs.existsSync(reportPath)) {
  throw new Error('Newman produced no report: ' + (execError || 'unknown error'));
}

const report = JSON.parse(fs.readFileSync(reportPath, 'utf-8'));
fs.unlinkSync(reportPath);

// A request that never got a response (API down, DNS failure) has no
// `response` and no `assertions` -- report it as a failed scenario
// instead of letting the audit itself crash on undefined.
const scenarios = report.run.executions.map((ex) => {
  const assertions = ex.assertions || [];
  return {
    name: ex.item.name,
    status_code: ex.response ? ex.response.code : null,
    request_error: ex.requestError ? String(ex.requestError.message || ex.requestError) : null,
    assertions_passed: assertions.filter((a) => !a.error).length,
    assertions_failed: assertions.filter((a) => !!a.error).length,
    failed_assertions: assertions.filter((a) => !!a.error).map((a) => a.assertion),
  };
});

return [{
  json: {
    incident_id: incidentId,
    collection_url: collectionUrl,
    base_url: baseUrl,
    stats: report.run.stats.assertions,
    scenarios,
    all_passed: report.run.stats.assertions.failed === 0 && scenarios.every((s) => !s.request_error),
  },
}];
